def hyperlink(pp,label,url):
    from docx.opc.constants import RELATIONSHIP_TYPE as RT
    rel=pp.part.relate_to(url,RT.HYPERLINK,is_external=True)
    link=OxmlElement('w:hyperlink');link.set(qn('r:id'),rel)
    r=OxmlElement('w:r');props=OxmlElement('w:rPr')
    color=OxmlElement('w:color');color.set(qn('w:val'),'1F4E79');props.append(color)
    sz=OxmlElement('w:sz');sz.set(qn('w:val'),'22');props.append(sz)
    szcs=OxmlElement('w:szCs');szcs.set(qn('w:val'),'22');props.append(szcs)
    direction=OxmlElement('w:rtl');direction.set(qn('w:val'),'1');props.append(direction)
    r.append(props);tx=OxmlElement('w:t');tx.text=label;r.append(tx);link.append(r);pp._p.append(link)

page('מקורות ושיטת הבדיקה')
p('הקישורים הבאים נפתחים מתוך המסמך. מספר המקור מופיע ליד הטענה או בטבלת הציוד. מקורות רשמיים של ממשלות, צבאות, ארגונים בינלאומיים וסוכנויות מחקר משמשים לרקע. מקורות יצרנים משמשים לתכונות, הזמנות ומסירות; קטלוג יצרן לבדו אינו מספיק כדי לקבוע כשירות מבצעית.')
p('נתוני הבנק העולמי נקראו ישירות מממשק הנתונים. מידע ציוד ישן מצוטט רק לזיהוי משפחת מערכת, ומגבלות כשירות נבדקות מול דיווחים עדכניים. מועד מסירה מתוכנן אינו מועד כניסה לכשירות מלאה. סטטוס לפני יישום ייבדק מחדש, במיוחד בפרויקטים שסומנו רכש, פיתוח או אימות.')
p('לא נעשה שימוש בנתונים מסווגים או בהשערת מלאי נשק מדויק. המסמך אינו מתחייב שכל מערכות המדינה מופיעות ברשימה. הוא בוחר מערכות שנותנות מגוון ותפקידים במשחק, ושומר פריטים בלתי מאומתים מחוץ לסגל הבסיס. כל המלצת משחק היא פרשנות תכנונית, ולא טענה של הגוף שמופיע במקור.')
for idx,(title,items) in enumerate(SOURCES):
    if idx>0: page(title)
    else: h(title)
    for code,label,url in items:
        pp=doc.add_paragraph();rtl(pp);pp.paragraph_format.space_after=Pt(10)
        runs(pp,'['+code+']\u00a0\u00a0',11,bold=True);hyperlink(pp,label,url)
    if idx==0:
        h('קבצים מקומיים שנבדקו')
        p('national_profile.gd, force_catalog.gd, national_arsenal.gd, economy.gd, war_costs.gd, cabinet.gd, un.gd, un_data.gd, wmd.gd ו־cbrn_data.gd. נבדקו גם מסמכי המחקר המקומיים על סגל הכוחות, הארסנל ומדינות נוספות. בדיקת הקוד הייתה לקריאה בלבד.')

